/*
 * @file  esp32-s31nrv32.S
 * @brief Startup for Espressif ESP32-S31NRV32 (ESP32-S31, CLIC interrupt controller).
 *        Generated by scripts/espressif_mcus.py - do not edit, change the generator instead.
 *
 * The ROM bootloader loads every segment of the image into SRAM, so .data needs no copy.
 */

    .section .text.entry, "ax"
    .global _start
    .type _start, @function
_start:
    csrci mstatus, 0x8
    .option push
    .option norelax
    la gp, __global_pointer$
    .option pop
    la sp, __stack_top
    la tp, __tls_base

    /* CLIC mode (MTVEC.MODE = 3): with selective hardware vectoring off every trap enters at MTVEC[31:6] << 6. */
    la t0, _trap_entry
    ori t0, t0, 3
    csrw mtvec, t0

    /* Clear .bss */
    la a0, __bss_start
    la a1, __bss_end
    bgeu a0, a1, 2f
1:
    sw zero, 0(a0)
    addi a0, a0, 4
    bltu a0, a1, 1b
2:
    call SystemInit
    call __libc_init_array
    li a0, 0
    li a1, 0
    call main
3:
    j 3b
    .size _start, . - _start

/* Common trap entry: saves the caller-saved registers, dispatches interrupts or reports the exception. */
    .section .text.trap, "ax"
    .balign 0x40
    .global _trap_entry
    .type _trap_entry, @function
_trap_entry:
    addi sp, sp, -64
    sw ra, 0(sp)
    sw t0, 4(sp)
    sw t1, 8(sp)
    sw t2, 12(sp)
    sw a0, 16(sp)
    sw a1, 20(sp)
    sw a2, 24(sp)
    sw a3, 28(sp)
    sw a4, 32(sp)
    sw a5, 36(sp)
    sw a6, 40(sp)
    sw a7, 44(sp)
    sw t3, 48(sp)
    sw t4, 52(sp)
    sw t5, 56(sp)
    sw t6, 60(sp)
    csrr a0, mcause
    bltz a0, 4f
    csrr a1, mepc
    call Exception_Handler
    j 5f
4:
    call __esp_interrupt_dispatch
5:
    lw ra, 0(sp)
    lw t0, 4(sp)
    lw t1, 8(sp)
    lw t2, 12(sp)
    lw a0, 16(sp)
    lw a1, 20(sp)
    lw a2, 24(sp)
    lw a3, 28(sp)
    lw a4, 32(sp)
    lw a5, 36(sp)
    lw a6, 40(sp)
    lw a7, 44(sp)
    lw t3, 48(sp)
    lw t4, 52(sp)
    lw t5, 56(sp)
    lw t6, 60(sp)
    addi sp, sp, 64
    mret
    .size _trap_entry, . - _trap_entry

/* Default handlers: endless loops, overridden by functions of the same name. */
